opencode_json:
{
  "$schema": "https://opencode.ai/config.json",
  "agent": {
    "build": {
      "permission": {
        "*": "allow",
        "question": "deny",
        "webfetch": "deny",
        "websearch": "deny"
      }
    },
    "revisor": {
      "description": "Revisa cambios",
      "mode": "subagent",
      "model": "rayito-openai/modelo-b",
      "permission": {
        "*": "allow",
        "edit": "deny",
        "question": "deny",
        "webfetch": "deny",
        "websearch": "deny"
      },
      "prompt": "Revisa el diff."
    }
  },
  "autoupdate": false,
  "enabled_providers": [
    "rayito-openai"
  ],
  "mcp": {
    "docs": {
      "enabled": true,
      "type": "remote",
      "url": "http://127.0.0.1:18004/mcp"
    },
    "local": {
      "command": [
        "mcp-server",
        "--stdio"
      ],
      "enabled": true,
      "environment": {
        "MODO": "x"
      },
      "timeout": 2500,
      "type": "local"
    }
  },
  "model": "rayito-openai/modelo-a",
  "provider": {
    "rayito-openai": {
      "models": {
        "modelo-a": {},
        "modelo-b": {}
      },
      "npm": "@ai-sdk/openai-compatible",
      "options": {
        "apiKey": "placeholder-not-a-secret",
        "baseURL": "http://127.0.0.1:18003/v1"
      }
    }
  },
  "share": "disabled",
  "small_model": "rayito-openai/modelo-a",
  "snapshot": false,
  "tui": {
    "scroll_speed": 3
  }
}
